inputs = ['uwcfh', 'wkade', 'xvj', 'uiwbc', 'kaw']
outputs = ['uwyyafh', 'wyykagwe', 'xvj', 'uiajxa', 'kawyy']

print("Pattern analysis:")
print("Looking for common patterns in the transformations...")

# Let's look at the transformations that are clearly insertions
print("\nInsertion cases:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    if len(inp) < len(outp):
        print(f"{i}: '{inp}' -> '{outp}' (insertion of {len(outp)-len(inp)} chars)")

# Let's look at replacement cases  
print("\nReplacement cases:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    if len(inp) == len(outp) and inp != outp:
        print(f"{i}: '{inp}' -> '{outp}' (replacement)")

print("\nLooking for repeated patterns...")
# Check if there are repeated substrings that might be targets for replacement
all_chars = set()
for s in inputs + outputs:
    all_chars.update(s)

print("All characters:", sorted(all_chars))

# Look for common replacements
replacements = {}
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    if inp != outp:
        # Create mapping of what changed
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                if (inp[j], outp[j]) not in replacements:
                    replacements[(inp[j], outp[j])] = []
                replacements[(inp[j], outp[j])].append((i, inp, outp))

print("Character replacements found:")
for (old_char, new_char), examples in replacements.items():
    print(f"  '{old_char}' -> '{new_char}': seen in examples {[(i, inp) for i, inp, _ in examples]}")

